package tn.esprit.partnerintelligence.observability;import jakarta.servlet.*;import jakarta.servlet.http.HttpServletRequest;import org.slf4j.MDC;import org.springframework.stereotype.Component;import java.io.IOException;import java.util.UUID;@Component public class TracingFilter implements Filter{ @Override public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain) throws IOException, ServletException { HttpServletRequest h=(HttpServletRequest)req; String trace=h.getHeader("X-Correlation-Id"); if(trace==null||trace.isBlank()) trace=UUID.randomUUID().toString(); MDC.put("traceId",trace); try{chain.doFilter(req,res);} finally{MDC.remove("traceId");}} }